import { SqliteClient } from "@effect/sql-sqlite-do";
import { assert, describe, it } from "@effect/vitest";
import { JobId, RoundId, TeamId } from "@surveybeat/domain";
import { SqliteStorage, Unlinkability } from "@surveybeat/testing";
import * as Effect from "effect/Effect";
import * as Reactivity from "effect/reactivity/Reactivity";
import * as Scope from "effect/Scope";
import { readdirSync, readFileSync } from "node:fs";
import { DatabaseSync } from "node:sqlite";
import { makeSqlActions } from "./SqlActions.ts";
import { makeSqlRounds } from "./SqlRounds.ts";

const migrationsDir = new URL("../migrations/", import.meta.url);
const roundId = RoundId.make("round-1");

const setup = Effect.gen(function* () {
  const db = new DatabaseSync(":memory:");
  for (const file of readdirSync(migrationsDir).filter((f) => f.endsWith(".sql")).sort()) {
    db.exec(readFileSync(new URL(file, migrationsDir), "utf8"));
  }
  db.prepare("INSERT INTO organization (id, name, ai_processing) VALUES ('org-1', 'Org 1', 1)").run();
  db.prepare("INSERT INTO team (id, name, time_zone) VALUES ('team-1', 'Team 1', 'UTC')").run();
  db.prepare(
    `INSERT INTO pulse (id, team_id, name, cadence, weekday, send_time, answer_window_days, reminders, anonymity_mode, distribution, created_at)
     VALUES ('pulse-1', 'team-1', 'Pulse 1', 'weekly', 'monday', '09:00', 3, 1, 'anonymous', 'invitation', 1000)`,
  ).run();
  db.prepare(
    `INSERT INTO round (id, pulse_id, team_id, status, planned_open_date, planned_open_at, planned_close_at, pulse_name, answer_window_days, reminders, anonymity_mode, distribution, created_at, updated_at)
     VALUES (?, 'pulse-1', 'team-1', 'closed', '2026-11-09', 1000, 9999999, 'Pulse 1', 3, 1, 'anonymous', 'invitation', 1000, 1000)`,
  ).run(roundId);
  db.prepare(
    `INSERT INTO schedule_job (id, round_id, type, due_at, status, payload, created_at, completed_at)
     VALUES ('job-old', ?, 'close', 5, 'completed', NULL, 1, 2)`,
  ).run(roundId);
  db.prepare(
    `INSERT INTO action (id, team_id, round_id, title, owner_id, status, created_at, updated_at)
     VALUES ('a1', 'team-1', ?, 'Second', 'p', 'committed', 20, 20),
            ('a2', 'team-1', ?, 'First', 'p', 'proposed', 10, 10),
            ('a3', 'team-1', ?, 'Done one', 'p', 'done', 5, 5)`,
  ).run(roundId, roundId, roundId);
  const sql = yield* SqliteClient.make({
    storage: SqliteStorage.makeSqliteStorage(db) as unknown as NonNullable<
      Parameters<typeof SqliteClient.make>[0]["storage"]
    >,
  }).pipe(Effect.provideService(Scope.Scope, yield* Scope.make()), Effect.provide(Reactivity.layer));
  return { db, sql, rounds: makeSqlRounds(sql, yield* Unlinkability.seededRandomBytes), actions: makeSqlActions(sql) };
});

describe("themes sql scratch", () => {
  it.effect("works end to end", () =>
    Effect.gen(function* () {
      const { db, rounds, actions } = yield* setup;
      assert.deepStrictEqual(db.prepare("SELECT id, status, due_at FROM schedule_job").all(), [
        { id: "job-old", status: "completed", due_at: 5 },
      ]);
      assert.deepStrictEqual(
        db.prepare("SELECT name FROM sqlite_master WHERE type='index' AND tbl_name='schedule_job' ORDER BY name").all().map((r) => r["name"]),
        ["schedule_job_due", "schedule_job_round"],
      );
      assert.strictEqual(yield* rounds.getRoundThemes(roundId), null);
      assert.strictEqual(yield* rounds.requestThemes(roundId, 100), true);
      assert.strictEqual(yield* rounds.requestThemes(roundId, 200), false);
      assert.deepStrictEqual(yield* rounds.getRoundThemes(roundId), { status: "pending", requestedAt: 100, attempts: 0 });
      yield* rounds.recordThemesAttemptFailed(roundId, 2);
      assert.deepStrictEqual(yield* rounds.getRoundThemes(roundId), { status: "pending", requestedAt: 100, attempts: 2 });
      yield* rounds.updateJobDueAtById(JobId.make("job-old"), 999);
      const stored = { themes: [{ label: "L", sentence: "S", supportingComments: 2 }], guide: null };
      yield* rounds.storeThemes(roundId, stored, 300);
      assert.deepStrictEqual(yield* rounds.getRoundThemes(roundId), { status: "ready", themes: stored });
      // store-once: a later give-up or store does nothing
      yield* rounds.giveUpThemes(roundId, 400);
      yield* rounds.storeThemes(roundId, { themes: [], guide: null }, 500);
      assert.deepStrictEqual(yield* rounds.getRoundThemes(roundId), { status: "ready", themes: stored });
      assert.deepStrictEqual(db.prepare("SELECT status FROM schedule_job WHERE id='job-old'").all(), [{ status: "completed" }]);
      assert.strictEqual(yield* rounds.requestThemes(RoundId.make("round-x"), 1), false === true ? true : false);
      // failed path
      const r2 = RoundId.make("round-2");
      db.prepare(`INSERT INTO round (id, pulse_id, team_id, status, planned_open_date, planned_open_at, planned_close_at, pulse_name, answer_window_days, reminders, anonymity_mode, distribution, created_at, updated_at)
        VALUES (?, 'pulse-1', 'team-1', 'closed', '2026-11-02', 1000, 9999999, 'Pulse 1', 3, 1, 'anonymous', 'invitation', 1000, 1000)`).run(r2);
      assert.strictEqual(yield* rounds.requestThemes(r2, 10), true);
      yield* rounds.giveUpThemes(r2, 20);
      assert.deepStrictEqual(yield* rounds.getRoundThemes(r2), { status: "failed" });
      const titles = yield* actions.getOpenActionTitlesForTeam(TeamId.make("team-1"));
      assert.deepStrictEqual(titles, ["First", "Second"]);
    }),
  );
});
EOF
